// Generate 200 mock OHLCV candles for testing
// In production, this would fetch real market data from exchange API

const candles = [];
const now = Date.now();
const oneHour = 3600000;
let basePrice = 42000; // Starting BTC price

for (let i = 199; i >= 0; i--) {
  const timestamp = new Date(now - (i * oneHour)).toISOString();

  // Simulate price movement with slight volatility
  const volatility = (Math.random() - 0.5) * 1000;
  const open = basePrice;
  const close = basePrice + volatility;
  const high = Math.max(open, close) + Math.random() * 200;
  const low = Math.min(open, close) - Math.random() * 200;
  const volume = 1000 + Math.random() * 5000;

  candles.push({
    timestamp,
    open,
    high,
    low,
    close,
    volume
  });

  basePrice = close; // Next candle starts where this one closed
}

return {
  json: {
    pair: 'BTC/USD',
    portfolio_balance: 100.0,
    current_position: 0,
    ohlcv: candles
  }
};

const strategyData = $input.all()[0].json;
