    pair: strategyData.pair,
    regime: strategyData.regime,
    strategy_name: selected,
    action: action,
    confidence: confidence,
    position_size_usd: position.size_usd || 0,
    risk_percentage: position.risk_percentage || 0,
    reasoning: strategyData.reasoning || 'No reasoning provided'
  }
};

